CREATE TABLE IF NOT EXISTS `homepage_sections` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `section_key` varchar(50) NOT NULL,
  `section_name` varchar(100) NOT NULL,
  `title` varchar(255) DEFAULT NULL,
  `heading` varchar(255) DEFAULT NULL,
  `subheading` text DEFAULT NULL,
  `content` longtext DEFAULT NULL,
  `media_url` varchar(255) DEFAULT NULL,
  `quote` varchar(255) DEFAULT NULL,
  `author` varchar(150) DEFAULT NULL,
  `extra_data` longtext DEFAULT NULL,
  `status` tinyint(1) NOT NULL DEFAULT 1,
  `sort_order` int(11) NOT NULL DEFAULT 0,
  `updated_at` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  UNIQUE KEY `section_key` (`section_key`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `homepage_sections` (`id`, `section_key`, `section_name`, `title`, `heading`, `subheading`, `content`, `media_url`, `quote`, `author`, `extra_data`, `status`, `sort_order`, `updated_at`)
VALUES ('1', 'hero_video', 'Hero Video & Stats Bar', 'AERIAL · BHOPAL CAMPUS', '32 acres of<br><em>living, learning</em> landscape.', 'From the medical quadrangle to the engineering labs — a bird\'s-eye view of the community our students call home.', '', 'new-media/image/hero/bhabha_2.mp4', '', '', '{\"poster\":\"new-media/image/campus-aerial.png\",\"stats\":[{\"number\":\"8500\",\"suffix\":\"+\",\"commas\":true,\"label\":\"STUDENTS\"},{\"number\":\"750\",\"suffix\":\"+\",\"commas\":false,\"label\":\"FACULTY\"},{\"number\":\"85\",\"suffix\":\"+\",\"commas\":false,\"label\":\"PROGRAMS\"},{\"number\":\"25\",\"suffix\":\"\",\"commas\":false,\"label\":\"INSTITUTES\"},{\"number\":\"300\",\"suffix\":\"+\",\"commas\":false,\"label\":\"RECRUITERS\"},{\"number\":\"20000\",\"suffix\":\"+\",\"commas\":true,\"label\":\"ALUMNI\"},{\"number\":\"2500\",\"suffix\":\"+\",\"commas\":true,\"label\":\"PUBLICATIONS\"},{\"number\":\"32\",\"suffix\":\" ac\",\"commas\":false,\"label\":\"CAMPUS\"}]}', '1', '1', '2026-09-30 15:06:46')
ON DUPLICATE KEY UPDATE `heading`=VALUES(`heading`), `subheading`=VALUES(`subheading`), `extra_data`=VALUES(`extra_data`), `status`=VALUES(`status`);

INSERT INTO `homepage_sections` (`id`, `section_key`, `section_name`, `title`, `heading`, `subheading`, `content`, `media_url`, `quote`, `author`, `extra_data`, `status`, `sort_order`, `updated_at`)
VALUES ('2', 'chancellor_welcome', 'Chancellor\'s Welcome', 'CHANCELLOR\'S MESSAGE', 'A legacy of <em>excellence</em>.<br>A vision for tomorrow.', '', '<p><strong>Dr. Sadhna Kapoor</strong> is the Chancellor of BHABHA University. A visionary and a selfless leader with exceptional entrepreneurial, interpersonal, social and administrative skills; Dr. Sadhna Kapoor is passionate about technology and innovation, community development, social service, and interdisciplinary teaching and research.</p>\n<p>She has been awarded the title of “Honorary Professor” by the Academic Union Oxford, UK, reflecting her global dedication to educational innovation and excellence.</p>', 'new-media/image/hero/sadhna-mam.mp4', '“We bridge academic brilliance with industrial pragmatism.”', 'DR. SADHNA KAPOOR · CHANCELLOR', '{\n    \"recognitions\": [\n        {\n            \"title\": \"UGC\",\n            \"label\": \"RECOGNISED\"\n        },\n        {\n            \"title\": \"MPPURC\",\n            \"label\": \"APPROVED\"\n        },\n        {\n            \"title\": \"AICTE\",\n            \"label\": \"APPROVED\"\n        }\n    ]\n}', '1', '2', '2026-09-25 16:34:12')
ON DUPLICATE KEY UPDATE `heading`=VALUES(`heading`), `subheading`=VALUES(`subheading`), `extra_data`=VALUES(`extra_data`), `status`=VALUES(`status`);

INSERT INTO `homepage_sections` (`id`, `section_key`, `section_name`, `title`, `heading`, `subheading`, `content`, `media_url`, `quote`, `author`, `extra_data`, `status`, `sort_order`, `updated_at`)
VALUES ('3', 'why_bhabha', 'Why Bhabha University', 'WHY BHABHA', 'A university built<br>for <em>impact.</em>', 'From academic excellence to ecosystem — every dimension of the Bhabha experience is engineered for academic depth, global mobility and lifelong opportunity.', '', '', '', '', '{\"features\":[{\"icon\":\"fa fa-certificate\",\"title\":\"UGC Recognised\",\"desc\":\"UGC recognised under 2(f)  with approvals from AICTE, PCI, BCI, DCI, NCTE.\",\"url\":\"\"},{\"icon\":\"fa fa-flask\",\"title\":\"Research Excellence\",\"desc\":\"120+ research labs, 250+ patents and 2,500+ publications.\",\"url\":\"\"},{\"icon\":\"fa fa-globe\",\"title\":\"Global Collaborations\",\"desc\":\"MoUs with 60+ international universities across 4 continents.\",\"url\":\"\"},{\"icon\":\"fa fa-mortar-board\",\"title\":\"Outstanding Placements\",\"desc\":\"98% placement rate with 300+ recruiters and packages up to ₹60 LPA.\",\"url\":\"\"},{\"icon\":\"fa fa-building-o\",\"title\":\"Smart Campus\",\"desc\":\"32-acre wifi-enabled green campus with smart classrooms.\",\"url\":\"\"},{\"icon\":\"fa fa-rocket\",\"title\":\"Innovation Ecosystem\",\"desc\":\"Incubation centre, student startups and industry mentoring.\",\"url\":\"\"}]}', '1', '3', '2026-09-26 16:34:52')
ON DUPLICATE KEY UPDATE `heading`=VALUES(`heading`), `subheading`=VALUES(`subheading`), `extra_data`=VALUES(`extra_data`), `status`=VALUES(`status`);

INSERT INTO `homepage_sections` (`id`, `section_key`, `section_name`, `title`, `heading`, `subheading`, `content`, `media_url`, `quote`, `author`, `extra_data`, `status`, `sort_order`, `updated_at`)
VALUES ('4', 'virtual_tour', 'Virtual Tour Showcase', 'Explore Campus · 360° Drone View', 'Virtual Tour of <em>Bhabha Campus</em>', 'Experience our breathtaking 32-acre green campus from the sky. Explore world-class academic blocks, research labs, sports arenas, and vibrant student life — all from right here.', '', 'upload/video/bhabha_video.mp4', '', '', '{\n    \"poster\": \"new-media/image/campus-aerial.png\",\n    \"badge1\": \"Live Campus Video\",\n    \"badge2\": \"Bhopal, MP\",\n    \"video_tabs\": [\n        {\n            \"label\": \"Aerial Drone\",\n            \"icon\": \"fa fa-plane\",\n            \"video_url\": \"upload/video/bhabha_video.mp4\"\n        },\n        {\n            \"label\": \"Campus Tour Video\",\n            \"icon\": \"fa fa-film\",\n            \"video_url\": \"new-media/image/hero/bhabha_2.mp4\"\n        },\n        {\n            \"label\": \"Academic & Labs\",\n            \"icon\": \"fa fa-flask\",\n            \"video_url\": \"new-media/image/hero/academic-lab.mp4\"\n        },\n        {\n            \"label\": \"Student Life\",\n            \"icon\": \"fa fa-graduation-cap\",\n            \"video_url\": \"new-media/image/hero/bhabha_4.mp4\"\n        }\n    ],\n    \"info_cards\": [\n        {\n            \"icon\": \"fa fa-tree\",\n            \"title\": \"32-Acre Green Campus\",\n            \"desc\": \"Eco-friendly lush green campus with solar energy, botanical gardens, and spacious plazas.\"\n        },\n        {\n            \"icon\": \"fa fa-university\",\n            \"title\": \"25 Institutes\",\n            \"desc\": \"Engineering, Medical, Dental, Pharmacy, Law, Agriculture & Management blocks.\"\n        },\n        {\n            \"icon\": \"fa fa-flask\",\n            \"title\": \"120+ Modern Labs\",\n            \"desc\": \"Hi-tech practical skill labs, research wings, and state-of-art computing centers.\"\n        },\n        {\n            \"icon\": \"fa fa-hospital-o\",\n            \"title\": \"500-Bed Hospital\",\n            \"desc\": \"Full-fledged multi-speciality teaching hospital & clinical training facility.\"\n        }\n    ],\n    \"cta_text\": \"Explore Full Virtual Tour\",\n    \"cta_url\": \"about.php#virtualTour\"\n}', '1', '4', '2026-09-30 15:06:24')
ON DUPLICATE KEY UPDATE `heading`=VALUES(`heading`), `subheading`=VALUES(`subheading`), `extra_data`=VALUES(`extra_data`), `status`=VALUES(`status`);

INSERT INTO `homepage_sections` (`id`, `section_key`, `section_name`, `title`, `heading`, `subheading`, `content`, `media_url`, `quote`, `author`, `extra_data`, `status`, `sort_order`, `updated_at`)
VALUES ('5', 'research_innovation', 'Research & Innovation', 'RESEARCH & INNOVATION', 'Knowledge that <em>moves</em> the<br>world forward.', 'From climate-resilient agriculture to AI in healthcare — our 120+ labs and research centres tackle the questions that matter most.', '', 'new-media/image/research-students.png', '', '', '{\n    \"metrics\": [\n        {\n            \"target\": 250,\n            \"value\": \"250\",\n            \"suffix\": \"+\",\n            \"prefix\": \"\",\n            \"commas\": false,\n            \"label\": \"PATENTS FILED\"\n        },\n        {\n            \"target\": 2500,\n            \"value\": \"2500\",\n            \"suffix\": \"+\",\n            \"prefix\": \"\",\n            \"commas\": true,\n            \"label\": \"PUBLICATIONS\"\n        },\n        {\n            \"target\": \"2.4\",\n            \"value\": \"2.4\",\n            \"suffix\": \" Cr\",\n            \"prefix\": \"\\u20b9\",\n            \"commas\": false,\n            \"label\": \"ACTIVE GRANTS\"\n        },\n        {\n            \"target\": 60,\n            \"value\": \"60\",\n            \"suffix\": \"+\",\n            \"prefix\": \"\",\n            \"commas\": false,\n            \"label\": \"GLOBAL MOUS\"\n        }\n    ],\n    \"highlight_icon\": \"fa fa-flask\",\n    \"highlight_text\": \"Featured: DST-funded sustainable energy research lab \\u2014 \\u20b92.4 Cr grant.\",\n    \"button_text\": \"EXPLORE RESEARCH \\u2192\",\n    \"button_url\": \"research.php\"\n}', '1', '5', '2026-09-25 16:58:17')
ON DUPLICATE KEY UPDATE `heading`=VALUES(`heading`), `subheading`=VALUES(`subheading`), `extra_data`=VALUES(`extra_data`), `status`=VALUES(`status`);

