VALUES ('6', 'global_network', 'Global Network & MoUs', 'INTERNATIONAL', 'A truly <em>global</em> network.', 'International Career Pathways: Empowering students with career opportunities in key global hubs including America, Europe, and the Middle East.', '', '', '', '', '{\"tags\":[\"Saudi Arabia (KSA)\",\"UAE\",\"USA\",\"UK\",\"Germany\",\"Canada\",\"Singapore\",\"Australia\"],\"button_text\":\"APPLY NOW →\",\"button_url\":\"enquiry.php\",\"yt_is_live\":0,\"yt_live_url\":\"\",\"yt_video_url\":\"https://www.youtube.com/watch?v=z1tHsYdaPLY\",\"yt_title\":\"Bhabha University Broadcast & Official Events\",\"yt_desc\":\"Watch live broadcasts of convocation, expert guest lectures, campus fests & university events.\",\"yt_channel_url\":\"https://www.youtube.com/channel/UCHyRBhcOyXt2CvTAW6JzP-g\",\"yt_channel_btn\":\"Watch on YouTube →\"}', '1', '6', '2026-09-26 13:54:41')
