VALUES ('8', 'degree_programs', 'Degree Programs (UG, PG, Diploma, Ph.D)', 'PROGRAMS OFFERED', '85+ programs across<br>every degree level.', 'Explore our comprehensive range of undergraduate, postgraduate, diploma, doctoral, and certificate programs.', NULL, NULL, NULL, NULL, '{\"source\":\"course_table\",\"description\":\"Live synced to Course Master\"}', '1', '0', '2026-10-08 16:58:31')
