INSERT INTO `homepage_sections` (`id`, `section_key`, `section_name`, `title`, `heading`, `subheading`, `content`, `media_url`, `quote`, `author`, `extra_data`, `status`, `sort_order`, `updated_at`)
VALUES ('9', 'infrastructure_grid', 'Campus Facilities & Infrastructure Grid', 'CAMPUS & INFRASTRUCTURE', 'World-class infrastructure<br>designed for excellence.', 'Modern campus equipped with advanced digital classrooms, 120+ research laboratories, sports complexes, hostels, and world-class amenities.', NULL, NULL, NULL, NULL, '{\"facilities\":{\"smart-classrooms\":{\"title\":\"Smart Classrooms\",\"badge\":\"Digital Learning\",\"desc\":\"Modern multimedia classrooms equipped with audio-visual equipment, digital podiums, interactive projection systems, and ergonomic seating to enhance interactive learning.\",\"image\":\"upload/infrastructure/83e285d874ee031ad471ea4df94a1945.jpg\",\"link\":\"infrastructure.php#smart-classrooms\"},\"research-labs\":{\"title\":\"Research & Innovation Labs\",\"badge\":\"Advanced Research\",\"desc\":\"Over 120+ cutting-edge laboratories for engineering, pharmacy, biotech, and applied sciences with sophisticated analytical instruments and modern computational facilities.\",\"image\":\"new-media/image/research-students.png\",\"link\":\"research.php\"},\"medical-centre\":{\"title\":\"Medical & Health Centre\",\"badge\":\"Healthcare & Wellness\",\"desc\":\"Dedicated on-campus medical centre with qualified doctors, round-the-clock nursing staff, first-aid support, and ambulance facility for student and faculty wellness.\",\"image\":\"upload/infrastructure/e24d4326ba8712763cc0e1484f66dc4d.jpg\",\"link\":\"infrastructure.php#health-centre\"},\"hostels\":{\"title\":\"Boys & Girls Hostels\",\"badge\":\"Student Living\",\"desc\":\"Safe, hygienic, and spacious residential facilities on campus with high-speed internet, recreational zones, 24/7 security surveillance, and mess facilities.\",\"image\":\"upload/infrastructure/f26b29937f258d4966b0be4de6bea02d.jpg\",\"link\":\"infrastructure.php#hostel\"},\"auditorium\":{\"title\":\"Auditorium & Seminar Hall\",\"badge\":\"Events & Convocations\",\"desc\":\"Acoustically treated grand auditorium with state-of-the-art sound systems, digital projection, and stage lighting for seminars, guest lectures, and convocations.\",\"image\":\"new-media/image/auditorium-hall-1.jpg\",\"link\":\"infrastructure.php#seminar-hall\"},\"open-auditorium\":{\"title\":\"Open Auditorium & Amphitheatre\",\"badge\":\"Cultural & Arts Arena\",\"desc\":\"Expansive open-air amphitheatre designed for cultural fests, annual functions, youth festivals, musical concerts, and student talent showcases.\",\"image\":\"new-media/image/auditorium-hall-2.jpg\",\"link\":\"infrastructure.php#open-auditorium\"},\"innovation-hub\":{\"title\":\"Innovation & Incubation Hub\",\"badge\":\"Startups & Patents\",\"desc\":\"University incubation centre providing mentorship, seed-grant assistance, prototyping workspace, and patent support to turn innovative ideas into successful enterprises.\",\"image\":\"new-media/image/bhabha-engineering-building.jpg\",\"link\":\"research.php#incubation\"},\"sports-complex\":{\"title\":\"Sports Complex & Gymnasium\",\"badge\":\"Athletics & Fitness\",\"desc\":\"World-class sports infrastructure featuring cricket grounds, football arena, basketball and volleyball courts, indoor games, and a modern fitness gymnasium.\",\"image\":\"upload/infrastructure/08ba91f6cd604afe6629e3c47afc8dfa.jpg\",\"link\":\"activities.php\"},\"cafeteria\":{\"title\":\"Central Cafeteria & Food Court\",\"badge\":\"Dining & Refreshments\",\"desc\":\"Spacious and hygienic food court offering nutritious multi-cuisine meals, healthy snacks, hot beverages, and social seating zones for campus life.\",\"image\":\"new-media/image/cafeteria.jpg\",\"link\":\"infrastructure.php#cafeteria\"},\"transport\":{\"title\":\"Transport & Bus Fleet\",\"badge\":\"Safe Commute\",\"desc\":\"Comprehensive fleet of 50+ university buses connecting all major sectors of Bhopal, Mandideep, Sehore, and adjoining regions with GPS tracking.\",\"image\":\"upload/infrastructure/6bcbeeeeb305c48b78ec2ad6cb45b4bf.jpg\",\"link\":\"infrastructure.php#transport\"}}}', '1', '0', '2026-09-29 13:05:34')
ON DUPLICATE KEY UPDATE `heading`=VALUES(`heading`), `subheading`=VALUES(`subheading`), `extra_data`=VALUES(`extra_data`), `status`=VALUES(`status`);

INSERT INTO `homepage_sections` (`id`, `section_key`, `section_name`, `title`, `heading`, `subheading`, `content`, `media_url`, `quote`, `author`, `extra_data`, `status`, `sort_order`, `updated_at`)
VALUES ('10', 'campus_life', 'Campus Life & Facilities (4 Highlights)', 'CAMPUS LIFE & INFRASTRUCTURE', 'World-class <em>facilities &amp; environment.</em>', 'A 32-acre expansive green ecosystem equipped with advanced academic infrastructure, renewable research facilities, live media broadcasting studios, and modern simulation laboratories.', NULL, NULL, NULL, NULL, '{\"cards\":[{\"badge\":\"Central Library\",\"icon\":\"fa fa-book\",\"title\":\"Central Library\",\"desc\":\"50,000+ books, digital e-journals & silent reading halls\",\"image\":\"images/library.jpg\",\"link\":\"infrastructure.php#library\"},{\"badge\":\"Green Campus\",\"icon\":\"fa fa-sun-o\",\"title\":\"Solar & Green Energy\",\"desc\":\"Eco-friendly campus with advanced solar research wing\",\"image\":\"images/solar.jpg\",\"link\":\"solar.php\"},{\"badge\":\"Community Radio\",\"icon\":\"fa fa-microphone\",\"title\":\"Radio Popcorn 90.4 FM\",\"desc\":\"Community radio station broadcasting student media projects\",\"image\":\"images/radio.jpg\",\"link\":\"radio.php\"},{\"badge\":\"Skill & Simulation\",\"icon\":\"fa fa-cogs\",\"title\":\"Modern Skill Labs\",\"desc\":\"Hands-on training facilities for engineering, pharmacy and nursing\",\"image\":\"images/skill_lab.jpg\",\"link\":\"infrastructure.php#labs\"}]}', '1', '0', '2026-10-05 16:24:43')
ON DUPLICATE KEY UPDATE `heading`=VALUES(`heading`), `subheading`=VALUES(`subheading`), `extra_data`=VALUES(`extra_data`), `status`=VALUES(`status`);

INSERT INTO `homepage_sections` (`id`, `section_key`, `section_name`, `title`, `heading`, `subheading`, `content`, `media_url`, `quote`, `author`, `extra_data`, `status`, `sort_order`, `updated_at`)
VALUES ('11', 'hall_of_fame', 'Hall of Fame & Placement Highlights Slider', 'STUDENT ACHIEVEMENTS', 'Hall of Fame &amp; Placement Highlights', 'Celebrating the extraordinary milestones, elite packages, and national government selections of our alumni and graduating scholars.', NULL, NULL, NULL, NULL, '{\"posters\":[{\"src\":\"upload/media/highest-package-60lpa.png\",\"title\":\"Mr. Anurag Kumar - ₹60.0 LPA at CPP\",\"alt\":\"Mr. Anurag Kumar Highest Package 60 LPA Bhabha University\",\"category\":\"Highest Placement (₹60 LPA)\"},{\"src\":\"upload/media/alumni_harikesh_singh_ies_rank68.jpg\",\"title\":\"Harikesh Singh - AIR Rank 68 in UPSC IES 2025\",\"alt\":\"Harikesh Singh AIR Rank 68 UPSC IES Bhabha University\",\"category\":\"UPSC IES Selection\"},{\"src\":\"upload/media/alumni_shubham_srivastava_nhsrcl.jpg\",\"title\":\"Shubham Kumar Srivastava - ₹12.0 LPA at NHSRCL\",\"alt\":\"Shubham Kumar Srivastava NHSRCL 12 LPA Bhabha University\",\"category\":\"PSU Placement (₹12 LPA)\"},{\"src\":\"upload/media/alumni_rakesh_roy_dhariwal.jpg\",\"title\":\"Mr. Rakesh Kumar Roy - ₹7.44 LPA at Dhariwal Buildtech\",\"alt\":\"Mr. Rakesh Kumar Roy Dhariwal Buildtech Bhabha University\",\"category\":\"Corporate Placement\"},{\"src\":\"upload/media/alumni_anshuman_singh_ies.jpg\",\"title\":\"Anshuman Singh - Indian Engineering Services (UPSC IES)\",\"alt\":\"Anshuman Singh Selected in UPSC IES Bhabha University\",\"category\":\"UPSC IES Selection\"},{\"src\":\"upload/media/alumni_kamlesh_kumar_ies.jpg\",\"title\":\"Kamlesh Kumar - Indian Engineering Services (UPSC IES)\",\"alt\":\"Kamlesh Kumar Selected in UPSC IES Bhabha University\",\"category\":\"UPSC IES Selection\"},{\"src\":\"upload/media/alumni_nidhi_shukla_dte.jpg\",\"title\":\"Nidhi Shukla - Selected in DTE / PSU Placement\",\"alt\":\"Nidhi Shukla DTE PSU Placement Bhabha University\",\"category\":\"Govt / PSU Placement\"},{\"src\":\"upload/media/alumni_vikash_chandra_iit_kanpur.jpg\",\"title\":\"Vikash Chandra - M.Tech Selection at IIT Kanpur\",\"alt\":\"Vikash Chandra IIT Kanpur Selection Bhabha University\",\"category\":\"Higher Studies (IIT)\"}]}', '1', '0', '2026-09-29 13:05:35')
ON DUPLICATE KEY UPDATE `heading`=VALUES(`heading`), `subheading`=VALUES(`subheading`), `extra_data`=VALUES(`extra_data`), `status`=VALUES(`status`);

INSERT INTO `homepage_sections` (`id`, `section_key`, `section_name`, `title`, `heading`, `subheading`, `content`, `media_url`, `quote`, `author`, `extra_data`, `status`, `sort_order`, `updated_at`)
VALUES ('12', 'accreditations', 'Statutory Approvals & Accreditations (Logos)', 'ACCREDITATIONS & APPROVALS', 'Statutory Approvals &amp; Recognitions', 'Bhabha University is recognized and approved by premier national statutory authorities and regulatory councils.', NULL, NULL, NULL, NULL, '{\"items\":[{\"img\":\"images/ugc_new_logo.jpg\",\"alt\":\"UGC - University Grants Commission\",\"name\":\"UGC\",\"desc\":\"Section 2(f)\",\"link\":\"approvals.php\"},{\"img\":\"images/AICT.png\",\"alt\":\"AICTE - All India Council for Technical Education\",\"name\":\"AICTE\",\"desc\":\"Approved\",\"link\":\"approvals.php\"},{\"img\":\"images/PCI.png\",\"alt\":\"PCI - Pharmacy Council of India\",\"name\":\"PCI\",\"desc\":\"Approved\",\"link\":\"approvals.php\"},{\"img\":\"images/bci.png\",\"alt\":\"BCI - Bar Council of India\",\"name\":\"BCI\",\"desc\":\"Approved\",\"link\":\"approvals.php\"},{\"img\":\"images/dci.png\",\"alt\":\"DCI - Dental Council of India\",\"name\":\"DCI\",\"desc\":\"Approved\",\"link\":\"approvals.php\"},{\"img\":\"images/nci.png\",\"alt\":\"NCTE - National Council for Teacher Education\",\"name\":\"NCTE\",\"desc\":\"Approved\",\"link\":\"approvals.php\"},{\"img\":\"images/MPNRC.png\",\"alt\":\"MPNRC - Madhya Pradesh Nurses Registration Council\",\"name\":\"MPNRC\",\"desc\":\"Recognized\",\"link\":\"approvals.php\"},{\"img\":\"images/mp_govt_logo.jpg\",\"alt\":\"Government of Madhya Pradesh\",\"name\":\"MP Govt.\",\"desc\":\"Recognized\",\"link\":\"approvals.php\"},{\"img\":\"images/nch_logo.png\",\"alt\":\"NCH - National Commission for Homoeopathy\",\"name\":\"NCH\",\"desc\":\"Approved\",\"link\":\"approvals.php\"}]}', '1', '0', '2026-10-03 15:31:24')
